impl FormatSummary {
    /// Generate a [`Edit`] to remove unused positional arguments from a `format` call.
    pub(crate) fn remove_unused_positional_arguments_from_format_call(
        &self,
        unused_arguments: &[usize],
        call: &ast::ExprCall,
        locator: &Locator,
        stylist: &Stylist,
    ) -> Result<Edit> {
        let unused_arguments: Vec<usize> = unused_arguments
            .iter()
            .copied()
            .filter(|index| {
                *index < call.arguments.args.len()
                    && !self.autos.contains(index)
                    && !self.indices.contains(index)
            })
            .collect();

        let call_range = TextRange::new(call.func.start(), call.end());
        let source_code = locator.to_source_code().slice(call_range);
        transform_expression(source_code, stylist, |mut expression| {
            let call = match_call_mut(&mut expression)?;

            // Remove any unused arguments.
            let mut index = 0;
            call.args.retain(|_| {
                let is_unused = unused_arguments.contains(&index);
                index += 1;
                !is_unused
            });

            Ok(expression)
        })
        .map(|output| Edit::range_replacement(output, call.range()))
    }
}

